(function(w){var a=w.BVC_PASSAGE_RESEARCH_CONTENT=w.BVC_PASSAGE_RESEARCH_CONTENT||[];[{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"1SA_01_01_08_WORBS_READER_DERIVATIVE_v0.1_20261017","researchType":"WORBS","researchDepth":"CORE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/1SA_01_01_08_WORBS_READER_DERIVATIVE_v0.1_20261017.md","sourceSha256":"439fbba733865477f11397723074a540f642f9b54b811324460dbb5e816f5eb5","passage":{"book":"1sa","chapter":1,"v1":1,"v2":8,"ref":"사무엘상 1:1–8"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"예배의 길 위에 놓인 한나의 눈물","overview":["사무엘상은 왕의 즉위나 전쟁의 승리로 시작하지 않는다. 에브라임 산지의 한 가정, 해마다 실로 성소로 올라가는 가족, 그리고 자녀가 없어 고통받는 한나의 이야기로 문을 연다. 엘가나는 한나를 사랑하지만, 또 다른 아내 브닌나의 지속적인 괴롭힘과 자녀가 없는 현실을 해결하지 못한다. 예배를 드리는 날조차 한나는 울며 먹지 못한다."],"centralMessage":"사무엘상 1:1–8은 이스라엘의 새 시대가 시작될 무대를, 해결되지 않은 한 여성의 고통과 반복되는 예배의 자리에서 마련한다. 하나님의 주권을 고백하는 서술은 한나의 상처를 죄의 결과로 판정하지 않으며, 인간의 위로가 미치지 못하는 자리를 드러낸 뒤 한나가 하나님께 직접 말하게 될 다음 장면을 준비한다.","literaryStructure":[{"v1":1,"v2":2,"title":"왕궁이 아니라 한 가정에서 시작되는 이야기"},{"v1":3,"v2":3,"title":"실로로 올라가는 예배와 아직 드러나지 않은 균열"},{"v1":4,"v2":5,"title":"제물의 몫으로도 메워지지 않는 결핍"},{"v1":6,"v2":7,"title":"예배 때마다 반복되는 상처"},{"v1":8,"v2":8,"title":"사랑하지만 다 알지 못하는 남편의 질문"}],"sections":[{"id":"1sa1-1-2","v1":1,"v2":2,"title":"왕궁이 아니라 한 가정에서 시작되는 이야기","paragraphs":["첫 문장은 에브라임 산지의 라마다임소빔에 사는 엘가나를 소개하고, 그의 조상들을 거슬러 올라간다. 이처럼 인물의 거주지와 가계를 제시하는 방식은 앞으로 일어날 일을 한 가정의 구체적인 역사 속에 놓는다. 그러나 화자가 독자에게 먼저 알려 주는 결정적인 사실은 엘가나의 지위나 재산이 아니다. 그에게 한나와 브닌나라는 두 아내가 있으며, 브닌나에게는 자녀가 있고 한나에게는 없다는 사실이다. 이 대비가 뒤따르는 모든 장면의 정서적 출발점이 된다.","두 아내가 있다는 사실은 고대 사회의 가정 구조를 보여 주지만, 서술이 그 관계를 이상적인 모습으로 칭찬하는 것은 아니다. 오히려 두 사람의 처지가 비교되면서 한 가정 안의 상처와 경쟁이 전면에 나타난다. 창세기에서 사라와 하갈, 레아와 라헬 사이에 나타났던 긴장을 떠올리게 하지만, 인물들의 사정과 행동이 모두 같다고 볼 수는 없다. 이 연결이 중요한 이유는 성경이 출산과 계승의 문제를 다룰 때 인간의 통제 밖에 있는 한계와 그 안에서 벌어지는 관계의 갈등을 함께 보여 준다는 데 있다.","엘가나의 출신지인 라마다임소빔은 본문의 지리적 출발점이다. ‘에브라임 사람’이라는 표현은 이 지역과의 연관을 나타내지만, 그것만으로 그의 혈통 전체를 확정할 수는 없다. 또한 고대 지명을 현대의 특정 지점과 일대일로 대응시키는 데에는 별도의 증거가 필요하다. 본문이 우선 알려 주는 것은 이 가족이 에브라임 산지에서 살았다는 사실이다."]},{"id":"1sa1-3-3","v1":3,"v2":3,"title":"실로로 올라가는 예배와 아직 드러나지 않은 균열","paragraphs":["엘가나는 해마다 자기 성읍에서 실로로 올라가 ‘만군의 여호와’께 경배하고 제사를 드린다. 가족의 삶에는 정기적인 예배의 리듬이 있다. 여기서 ‘올라간다’는 말은 성소를 향한 이동을 서술하며, 본문은 그 순례가 반복되었다는 사실을 강조한다. 출발지와 목적지는 제시되지만 이동 경로, 걸린 시간, 중간 기착지는 기록되지 않는다. 따라서 이 구절을 세밀한 고대 도로 지도로 바꾸기보다, 가족이 일상에서 성소로 나아가는 반복적인 움직임으로 이해하는 것이 적절하다.","‘만군의 여호와’(יְהוָה צְבָאוֹת, 여호와 체바오트)는 여호와의 통치와 권능을 드러내는 호칭이다. 여기서 ‘만군’을 곧바로 이스라엘의 군대 하나로만 좁힐 필요는 없다. 이 호칭은 앞으로 왕과 전쟁, 나라의 운명을 다룰 사무엘상 전체를 내다보게 한다. 그러나 첫 장면에서 그 하나님께 나아가는 사람은 군대를 이끄는 왕이 아니라 자녀가 없어 슬퍼하는 한 여성의 가족이다. 큰 역사를 다스리시는 하나님과 한 사람의 고통이 같은 서사의 첫머리에 놓인 것이다.","화자는 실로에 엘리의 두 아들 홉니와 비느하스가 제사장으로 있었다는 사실도 미리 말한다. 3절만으로 그들의 죄를 모두 알 수는 없지만, 뒤따르는 2장에서는 그들이 제사를 멸시하고 성소를 더럽히는 행위가 드러난다. 그러므로 이 짧은 소개는 성소 자체가 아무 문제 없는 공간이라는 기대를 서서히 흔든다. 한나의 가정에서 일어나는 상처와 제사장 집안의 위기는 아직 다른 장면이지만, 이야기의 진행 속에서 서로를 비추게 된다."]},{"id":"1sa1-4-5","v1":4,"v2":5,"title":"제물의 몫으로도 메워지지 않는 결핍","paragraphs":["제사를 드리는 날 엘가나는 브닌나와 그 자녀들에게 제물의 몫을 나누어 주고 한나에게도 몫을 준다. 이 식사 장면은 가족이 함께 제사에 참여하고 있음을 보여 주면서 동시에 자녀가 있는 사람과 없는 사람의 차이를 다시 드러낸다. 한나를 사랑한다는 엘가나의 마음은 분명하지만, 그 사랑이 곧 한나의 고통을 없애 주지는 못한다.","5절의 히브리어 표현 מָנָה אַחַת אַפָּיִם(마나 아하트 압파임)은 번역이 쉽지 않다. 흔히 한나에게 ‘갑절의 몫’을 주었다고 옮기지만, ‘특별한 몫’이나 ‘한 몫’으로 이해하는 견해도 있다. 따라서 제물의 정확한 양을 확정해 이야기의 의미를 세우는 것은 조심해야 한다. 본문에서 분명한 것은 엘가나가 한나를 사랑했다는 사실과, 그 사랑에도 불구하고 한나의 태가 닫혀 있었다는 사실이다.","서술자는 ‘여호와께서 그의 태를 닫으셨다’고 말한다. 이 표현은 생명이 인간의 뜻대로 주어지는 것이 아니라는 신앙적 인식을 드러낸다. 그러나 한나가 어떤 잘못을 저질렀기 때문에 자녀를 갖지 못했다는 설명은 본문 어디에도 없다. 하나님의 주권을 고백하는 서술을 고통받는 사람에 대한 도덕적 판결로 바꾸면, 본문이 말하지 않는 원인을 만들어 내게 된다."]},{"id":"1sa1-6-7","v1":6,"v2":7,"title":"예배 때마다 반복되는 상처","paragraphs":["브닌나는 한나를 심히 격동시키고 괴롭힌다. 히브리어 צָרָה(차라)는 문맥에 따라 경쟁 상대나 적대적인 처지의 사람을 가리킬 수 있다. 여기서는 같은 남편을 둔 다른 아내가 한나에게 적대적으로 행동하는 관계를 드러낸다. 이어지는 자극과 괴롭힘의 표현은 한나가 단순히 남과 비교하며 속상해한 정도가 아니라, 타인의 의도적인 공격을 겪고 있음을 보여 준다.","7절은 이 일이 ‘매년’ 되풀이되었다고 말한다. 한나의 눈물은 하루의 돌발적인 감정이 아니다. 실로에 올라가는 정기적인 예배의 때마다 괴롭힘이 다시 시작되었고, 그 결과 한나는 울며 먹지 못했다. 제사의 식사가 가족의 기쁨과 교제를 나타낼 수 있는 자리에서, 한나는 그 식사에 참여할 힘마저 잃는다. 성소를 찾는 신앙생활과 깊은 슬픔이 같은 시간에 존재한다는 사실이 이 장면의 긴장이다.","이 대목은 브닌나의 공격을 정당화하지도, 한나의 눈물을 믿음이 부족하다는 표시로 설명하지도 않는다. 서술자는 오히려 상처의 반복을 충분히 보여 줌으로써 다음 장면에서 한나가 왜 자신의 마음을 여호와 앞에 쏟아 놓는지 이해하게 한다. 한나의 기도는 아무 문제 없는 사람이 신앙적 열심을 보이기 위해 덧붙인 행동이 아니라, 오래 지속된 고통 속에서 나오는 말이다."]},{"id":"1sa1-8-8","v1":8,"v2":8,"title":"사랑하지만 다 알지 못하는 남편의 질문","paragraphs":["엘가나는 한나에게 왜 울며 먹지 않고 마음이 슬프냐고 묻는다. 그는 아내의 눈물과 식욕 상실을 알아차린다. 이어 ‘내가 그대에게 열 아들보다 낫지 아니하냐’고 말하며 자신의 사랑으로 한나를 위로하려 한다. ‘열 아들’은 많은 아들을 가리키는 강조 표현으로 읽을 수 있으며, 실제 자녀 수를 세는 정보로 취급할 필요는 없다.","그의 말에는 애정이 담겨 있지만, 한나가 겪는 고통을 충분히 이해하지 못하는 한계도 드러난다. 남편의 사랑은 소중하지만 브닌나의 공격과 자녀가 없다는 현실을 대신 해결해 주지는 못한다. 본문은 엘가나를 악인으로 단정하지 않는다. 동시에 그가 좋은 뜻으로 건넨 말이 한나의 눈물을 멈추게 했다고도 기록하지 않는다.","이렇게 첫 여덟 절은 해결책을 내놓지 않은 채 멈춘다. 독자는 한나의 처지를 알게 되었지만, 아직 한나 자신의 긴 기도를 듣지 못했다. 9절 이후 한나는 일어나 여호와 앞에 나아가며, 자신의 쓰라린 마음을 직접 말한다. 첫 단락의 문학적 역할은 한나의 고통을 서둘러 설명하거나 없애는 데 있지 않다. 그 고통을 있는 그대로 드러내고, 이제 하나님 앞에서 시작될 새로운 대화를 준비하는 데 있다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"alternativeReadings":[{"title":"‘만군의 여호와’라는 호칭의 기능","paragraphs":["צְבָאוֹת(체바오트)는 ‘군대들’, ‘무리들’과 관련된 말이다. 그 지시 범위를 하나의 군사 조직으로 한정하기보다는 여호와의 광범한 통치권을 드러내는 칭호로 읽는 것이 자연스럽다. 왕정으로 향하는 책의 도입부에 이 이름이 놓였다는 점은 의미가 있지만, 이 한 구절만으로 후대의 왕권 신학 전체가 이미 상세히 전개되었다고 말할 수는 없다."]},{"title":"5절의 제물 분배와 번역의 한계","paragraphs":["מָנָה אַחַת אַפָּיִם의 정확한 뜻에는 논의가 남아 있다. ‘갑절’이라는 익숙한 번역을 유일한 정답으로 삼거나, 반대로 엘가나가 한나를 홀대했다고 결론 내리기 어렵다. 서술이 직접 밝히는 사랑과 한나의 지속되는 슬픔을 함께 읽어야 한다."]},{"title":"하나님의 주권과 인간의 가해를 구별하기","paragraphs":["5–6절의 ‘여호와께서 태를 닫으셨다’는 서술과 브닌나가 한나를 괴롭혔다는 서술은 서로 다른 행위를 말한다. 본문은 한나의 불임을 하나님 주권 아래에 놓지만, 그 사실을 브닌나의 모욕에 대한 정당화로 사용하지 않는다. 또한 고난의 원인을 한나 개인의 죄에서 찾지 않는다. 이 구분은 본문 자체의 인물 평가를 보존하는 데 중요하다."]},{"title":"앞뒤 본문과의 관계","paragraphs":["창세기 29–30장의 레아와 라헬 이야기는 출산과 가족 내 경쟁이 서로 얽힐 때 생기는 긴장을 보여 준다. 사무엘상 1:9–20은 한나가 이 고통을 여호와 앞에 말하고, 1:21–28은 받은 아들을 봉헌하는 과정을 전한다. 사무엘상 2:1–10의 한나의 노래는 개인의 경험을 낮은 자를 높이시고 교만한 자를 낮추시는 하나님의 통치로 확장한다. 이 뒤의 내용을 첫 여덟 절에 미리 모두 집어넣기보다, 첫 장면이 제기한 질문이 어떻게 전개되는지를 따라 읽는 편이 좋다."]}],"relatedResearch":[],"readerSources":[],"notes":["성경 본문: 대한성서공회, 『성경전서 개역한글판』, 사무엘상 1:1–8; 창세기 16장, 29–30장; 사무엘상 1:9–2:10. 히브리어 표현은 사무엘상 1:1–8의 마소라 본문을 기준으로 검토하였다."],"sourceNotice":""},{"schema":"JBC_PASSAGE_READER_COMMENTARY_v1","researchId":"1SA_01_09_20_WORBS_READER_DRAFT_20261018","researchType":"WORBS","researchDepth":"CORE","sourcePath":"G:/내 드라이브/Jude_Lee_OS/01_PROJECTS/01_목회연구_WORBS_BICS/WORKING_COMMENTARY66_20261011/1SA_01_09_20_WORBS_READER_DRAFT_20261018.md","sourceSha256":"6c88c2f387bb95e9f6fb2a1af0434d0d7dda3b7614d2f07c0aff4582bb41cefc","passage":{"book":"1sa","chapter":1,"v1":9,"v2":20,"ref":"사무엘상 1:9–20"},"projectionStatus":"INTERNAL_READER_PROJECTION","professionalStatus":"CANDIDATE_REVIEW_ONLY","qualityStatus":"CANDIDATE_RESEARCH_REVIEW_REQUIRED","externalRelease":"NOT_AUTHORIZED","generatedByProject":"01_목회연구_WORBS_BICS","professionalAuthorityOwner":"01_목회연구_WORBS_BICS","title":"# 눈물에서 기억하심으로","overview":["실로 성소에서의 식사와 가족 갈등을 보여 준 앞 단락(1:1–8)에 이어, 한나는 일어나 여호와께 자신의 괴로운 마음을 아뢴다. 그는 아들을 구하면서도 그 아들을 평생 여호와께 드리겠다고 서원한다. 그러나 기도하는 입술만 보고 엘리는 한나를 술 취한 사람으로 오해한다. 한나가 자신을 설명하자 엘리는 평안을 빌고, 한나는 아직 아무 결과도 확인하지 못한 채 식사를 다시 시작한다. 이튿날 가족은 예배를 드린 뒤 집으로 돌아가고, 서술자는 여호와께서 한나를 기억하셨다고 전한다. 마침내 아들이 태어나고 한나는 그 이름을 사무엘이라 부른다."],"centralMessage":"이 단락의 전환점은 한나가 간절히 기도했다는 사실만이 아니라, 그 기도가 향하는 여호와께서 그를 기억하셨다는 서술에 있다. 한나의 고통은 성급히 지워지지 않으며, 성소의 제사장조차 그를 처음에는 알아보지 못한다. 그러나 한나는 자신의 삶을 하나님 앞에 숨기지 않고 말하며, 하나님께 받은 생명을 자신의 소유로만 붙잡지 않겠다고 약속한다. 개인의 간구와 하나님의 기억하심이 만나는 이 이야기는 뒤에 이스라엘의 말씀과 왕권의 역사를 이끌 사무엘의 출생을 준비한다.","literaryStructure":[{"v1":9,"v2":10,"title":"한나가 일어나고 성소의 문턱이 보인다"},{"v1":11,"v2":11,"title":"‘보시고 기억하소서’라는 서원"},{"v1":12,"v2":14,"title":"입술은 움직이지만 소리는 들리지 않는다"},{"v1":15,"v2":16,"title":"‘내 마음을 쏟아 놓았습니다’라는 해명"},{"v1":17,"v2":18,"title":"결과보다 먼저 찾아온 식사와 얼굴의 변화"},{"v1":19,"v2":20,"title":"예배를 마치고 돌아간 자리에서 하나님이 기억하신다"}],"sections":[{"id":"1sa1-9-10","v1":9,"v2":10,"title":"한나가 일어나고 성소의 문턱이 보인다","paragraphs":["앞 단락에서 한나는 울며 먹지 못했고, 남편 엘가나의 애정 어린 질문도 그 고통을 해결하지 못했다(1:7–8). 9절의 첫 동사, ‘일어났다’는 말은 정지해 있던 장면을 움직인다. 이제 이야기는 가족의 대화에서 한나 자신의 행동으로 중심을 옮긴다. 한나가 무엇을 먹었는지에 관해서는 번역상의 표현 차이가 있을 수 있지만, 여기서 중요한 것은 식사가 끝난 뒤 한나가 성소에서 기도의 자리로 나아간다는 사건의 순서이다.","서술자는 엘리 제사장이 여호와의 성전 문설주 곁 의자에 앉아 있다고 덧붙인다. ‘성전’에 해당하는 히브리어 헤칼(הֵיכָל)은 이 장면에서 실로의 거룩한 건물을 가리킨다. 이를 곧바로 훗날 솔로몬이 지은 예루살렘 성전과 동일한 건축 형태로 이해할 필요는 없다. 본문은 엘리의 위치와 성소의 문턱을 보여 주지만, 건물의 세부 평면이나 당시 실로의 모든 시설을 재구성할 정보까지 주지는 않는다. 성소의 문턱은 뒤이어 한나의 기도를 지켜보는 엘리의 시선을 준비하는 문학적 장치이기도 하다.","10절은 한나가 ‘마음이 괴로워’ 여호와께 기도하고 크게 운다고 기록한다. 히브리어 마라트 네페쉬(מָרַת נָפֶשׁ)는 단순히 잠시 기분이 상했다는 뜻이 아니라, 존재의 깊은 곳까지 쓰라린 상태를 표현한다. 한나의 기도는 고통이 사라진 뒤 시작된 경건한 절차가 아니다. 바로 그 고통 속에서 여호와를 향한 말이 시작된다. 이 점에서 이야기는 인간의 감정을 부정하지 않으면서도, 그 감정이 하나님과의 관계 안에서 발화되는 과정을 보여 준다."]},{"id":"1sa1-11-11","v1":11,"v2":11,"title":"‘보시고 기억하소서’라는 서원","paragraphs":["한나의 말은 ‘만군의 여호와’를 부르는 데서 시작한다. 앞 단락에서 가족이 해마다 예배하던 바로 그 하나님께 이제 한나가 자기 사정을 직접 말한다. 그가 먼저 구하는 것은 즉각적인 해결책의 기술이 아니라, 하나님이 자신의 고통을 보시고 자신을 기억하시며 잊지 않으시는 일이다. 히브리어의 ‘보시고 또 보신다면’(רָאֹה תִרְאֶה)은 같은 동사의 강조된 결합이다. 이는 하나님이 한나의 현실을 참으로 주목해 주시기를 간청하는 절실함을 드러낸다.","‘기억하소서’(זְכַרְתַּנִי)는 하나님이 정보를 잊어버렸다가 다시 떠올려야 한다는 뜻으로 읽기보다, 하나님이 한나의 처지를 돌보시고 행동해 주시기를 구하는 언어로 이해하는 것이 적절하다. 창세기 8:1에서 하나님이 노아를 기억하신 뒤 홍수의 물이 물러가고, 출애굽기 2:24에서 하나님이 언약을 기억하신 뒤 이스라엘의 구원 이야기가 전개되는 것과 비교할 수 있다. 다만 이 평행 본문들이 한나의 기도를 기계적으로 재현한다는 뜻은 아니다. ‘기억’이라는 표현이 하나님의 실제적인 돌보심과 연결된다는 정경적 공명을 보여 준다.","한나는 아들을 달라고 구하면서 그를 평생 여호와께 드리고 머리에 삭도를 대지 않겠다고 서원한다. ‘아들’을 뜻하는 표현은 히브리어로 ‘남자의 씨’에 가까운 말이지만, 여기서는 남자아이를 구하는 뜻으로 이해된다. 한나는 자신이 얻기를 간절히 원하는 존재를 자신의 삶에 영구히 붙들어 두겠다고 말하지 않는다. 아직 받지 않은 아들을 하나님께 속한 삶으로 드리겠다는 약속이 청원과 함께 놓인다. 이것을 고통 없는 모범적 헌신으로 미화할 수는 없다. 아이를 원한다는 소망과 아이를 하나님께 드리겠다는 결단 사이의 긴장이 바로 서원의 무게이다.","삭도를 대지 않겠다는 말은 민수기 6장의 나실인 규례 및 사사기 13장의 삼손 이야기와 관련하여 읽을 수 있다. 그러나 사무엘상 1:11의 히브리어 본문 자체는 나실인이라는 명칭을 사용하거나 모든 나실인 규정을 열거하지 않는다. 따라서 사무엘의 봉헌이 나실인적 성격을 띤다고 설명하는 것과 그가 특정 규례의 모든 조항을 그대로 따랐다고 확정하는 것은 구별해야 한다."]},{"id":"1sa1-12-14","v1":12,"v2":14,"title":"입술은 움직이지만 소리는 들리지 않는다","paragraphs":["기도가 길어지는 동안 엘리는 한나의 입을 지켜본다. 한나는 마음속으로 말하고 입술만 움직였으므로 소리가 들리지 않는다. 서술자는 독자에게 이미 한나의 기도 내용을 알려 주었지만, 엘리는 그 내용을 듣지 못한다. 독자가 아는 것과 등장인물이 아는 것 사이의 차이가 오해를 낳는 장면이다. 엘리는 한나를 술 취한 사람으로 판단하고 언제까지 취해 있겠느냐고 꾸짖는다.","본문은 엘리가 왜 그런 추정을 했는지 그의 내면을 설명하지 않는다. 당시 예배의 구체적 관습을 모두 알 수 있는 것도 아니다. 따라서 이 한 장면만으로 고대 이스라엘에서 소리 없는 기도가 금지되었다고 단정할 수 없다. 분명한 것은 엘리의 판단이 틀렸다는 사실이다. 그가 성소의 제사장으로 앉아 있어도 한나의 속마음을 제대로 보지 못한다. 성소 안의 종교적 권위와 실제 고통을 분별하는 능력이 반드시 일치하지 않음을 이 장면은 보여 준다.","엘리를 이 순간부터 전적으로 악한 인물로 그리는 것도 본문보다 앞서가는 해석이다. 뒤에서 그는 한나의 설명을 듣고 평안을 빌어 준다(17절). 다만 그의 첫 판단이 고통받는 사람을 더 상하게 할 수 있는 오해였다는 점은 가볍게 넘어갈 수 없다. 사무엘상 2장에서 드러나는 엘리 집안의 문제는 이 장면을 다시 생각하게 하지만, 후속 서술의 모든 평가를 1:13–14에 한꺼번에 덧씌우지 않는 편이 정확하다."]},{"id":"1sa1-15-16","v1":15,"v2":16,"title":"‘내 마음을 쏟아 놓았습니다’라는 해명","paragraphs":["한나는 제사장에게 거칠게 맞서거나 자신의 기도를 철회하지 않는다. 자신은 술이나 독주를 마신 사람이 아니라 ‘마음이 괴로운 여자’라고 설명한다. 앞서 서술자가 알려 준 고통의 실체를 이제 한나 자신의 입으로 듣게 되는 것이다. 한나가 사용한 ‘내 영혼을 쏟아 놓았다’(וָאֶשְׁפֹּךְ אֶת־נַפְשִׁי)는 표현은 감정을 조금 드러냈다는 뜻보다 자신의 깊은 내면을 여호와 앞에 남김없이 내어 놓았다는 뜻을 전한다. ‘영혼’이라는 말은 몸과 분리된 어떤 부분만을 가리킨다기보다, 고통을 겪는 한 사람의 생명과 자아를 폭넓게 나타낸다.","16절에서 한나는 자신을 ‘불량한 여자’로 여기지 말라고 부탁한다. 여기의 ‘벨리알의 딸’에 해당하는 표현은 도덕적으로 불량한 사람을 가리키는 관용적 말로 이해할 수 있다. 이 표현은 2장에서 엘리의 아들들을 ‘불량자들’로 묘사하는 말과 연결되어 의미심장한 대조를 만든다. 한나는 그런 사람으로 오해받지만, 이어지는 이야기는 오히려 제사장 집안의 행실에 문제를 제기한다. 다만 이 대비를 보려면 2장의 후속 설명이 필요하며, 1:16 자체가 이미 엘리의 아들들에 대한 완전한 판결을 제시하는 것은 아니다.","한나는 자신의 말이 ‘많은 원통함과 격분’에서 나왔다고 설명한다. 이는 기도가 마음을 억지로 평온하게 만드는 형식이 아니라, 실제 원통함을 하나님께 말하는 행위임을 보여 준다. 한나가 서원을 했다는 사실이 그 고통의 크기를 줄이지 않는다. 오히려 본문은 기도의 진실성과 슬픔의 깊이를 함께 보존한다."]},{"id":"1sa1-17-18","v1":17,"v2":18,"title":"결과보다 먼저 찾아온 식사와 얼굴의 변화","paragraphs":["엘리는 한나의 말을 듣고 ‘평안히 가라’고 하며 이스라엘의 하나님께서 그의 구한 것을 주시기를 빈다. 그의 첫 말은 잘못된 단정이었지만, 이번에는 한나를 고발하는 대신 축복의 말로 보낸다. 엘리의 말은 문법상 하나님이 한나의 청원을 이루어 주시기를 바라는 축복으로 읽을 수 있다. 이를 그가 미래의 임신을 이미 확실히 알았다는 선언으로 확대할 근거는 본문에 없다.","한나는 제사장 앞에서 은혜를 입기를 바란다고 답하고 돌아가 음식을 먹는다. 그 얼굴은 더 이상 전과 같지 않다고 기록된다. 앞 단락에서 한나는 울며 먹지 못했다(7절). 이제 서술은 같은 ‘먹음’의 소재를 사용해 변화를 보여 준다. 중요한 것은 아직 19–20절의 출생 사건이 일어나지 않았다는 사실이다. 따라서 그의 변화는 이미 아들을 안았기 때문에 생긴 기쁨이 아니라, 하나님 앞에 마음을 쏟고 축복의 말을 들은 뒤 나타난 변화이다.","이 장면을 모든 기도가 반드시 원하는 결과를 얻는다는 보증으로 일반화해서는 안 된다. 본문은 한나에게 일어난 특정한 사건을 말한다. 동시에 이야기는 응답이 눈에 보이기 전에도 사람의 태도와 얼굴에 변화가 나타날 수 있다는 서사적 사실을 놓치지 않는다. ‘먹지 못함’에서 ‘먹음’으로의 전환은 이 단락의 섬세한 문학적 표지이다."]},{"id":"1sa1-19-20","v1":19,"v2":20,"title":"예배를 마치고 돌아간 자리에서 하나님이 기억하신다","paragraphs":["이튿날 가족은 일찍 일어나 여호와 앞에 경배하고 라마의 집으로 돌아간다. 본문은 실로에서 라마로의 귀환을 말하지만, 세부 경로와 이동 거리, 도중의 정착지까지 알려 주지는 않는다. 앞 단락의 연례 순례와 마찬가지로 지리적 정보는 출발과 귀환의 관계를 밝히는 범위에서 읽는 것이 타당하다. 이어 엘가나와 한나의 부부 관계가 간략히 언급된 뒤, ‘여호와께서 그를 기억하셨다’는 결정적인 문장이 놓인다.","이 문장은 11절의 간구에 대한 서사적 응답이다. 한나는 ‘기억하소서’라고 청했고, 서술자는 여호와께서 ‘기억하셨다’고 말한다. 출생을 향한 인간의 삶의 과정은 지워지지 않지만, 화자는 그 과정 위에 하나님의 돌보심을 놓는다. 기도의 성취를 한나의 말 자체가 지닌 어떤 힘으로 설명하기보다, 그 기도를 들으시는 하나님에게 중심을 둔다. 이는 앞 단락에서 여호와께서 한나의 태를 닫으셨다는 서술(5–6절)과도 긴장 속에 연결된다. 본문은 하나님의 주권을 말하면서도 한나의 고통을 죄의 벌로 규정하지 않는다.","‘때가 이르매’에 해당하는 표현은 시간이 흘렀음을 알려 줄 뿐, 임신과 출산의 정확한 연월일을 제공하지 않는다. 한나는 아들을 낳고 ‘사무엘’이라는 이름을 붙이며 여호와께 구하여 얻었다고 말한다. 여기서 ‘구하다’(שָׁאַל, 샤알)라는 동사는 엘리의 축복에 나타난 청원(17절)과 연결되고, 뒤의 봉헌 장면(27–28절)에서 다시 중요한 역할을 한다. 사무엘이라는 이름의 엄밀한 어원이 이 동사에서 직접 만들어졌다고 단정하기는 어렵다. 본문은 이름의 언어학적 기원만 설명하기보다, 한나가 그 아이를 ‘여호와께 구한 아들’로 이해한다는 신앙적 의미를 강조한다.","이렇게 1:9–20은 고통에서 기도로, 오해에서 해명으로, 눈물에서 식사로, 간구에서 기억하심과 출생으로 나아간다. 그러나 이야기는 출생으로 완전히 끝나지 않는다. 한나가 약속한 봉헌이 1:21–28에서 이루어지고, 2:1–10의 노래는 개인의 경험을 낮은 자를 높이시는 하나님의 통치로 확장한다. 독자는 지금 이 출생의 기쁨을 보면서도, 아이를 여호와께 드리겠다는 서원이 아직 남아 있음을 기억하게 된다."]}],"lexicalCards":[],"discoveries":[],"canonicalLinks":[],"theologicalSynthesis":[],"alternativeReadings":[{"title":"강조된 ‘보다’와 응답하는 ‘기억하다’","paragraphs":["11절의 רָאֹה תִרְאֶה는 히브리어 부정사 절대형과 활용 동사가 결합한 강조 표현이다. 이를 한국어에서 같은 동사를 두 번 기계적으로 반복할 필요는 없으며, ‘참으로 살펴보신다면’처럼 간청의 강도를 드러낼 수 있다. 11절의 זְכַרְתַּנִי와 19절의 וַיִּזְכְּרֶהָ는 ‘기억’이라는 같은 동사 어근을 사용해 청원과 응답을 연결한다. 이는 단어 하나의 신비한 효력보다 서술 전체의 연결을 이해하게 하는 중요한 관찰이다."]},{"title":"서원과 나실인 규례의 관계","paragraphs":["삭도를 대지 않겠다는 11절의 말은 민수기 6:1–21의 나실인 규례 및 사사기 13:5의 삼손 출생 예고를 떠올리게 한다. 그러나 마소라 본문에 나타나는 명시 사항은 평생의 봉헌과 머리털에 관한 약속이다. 고대 그리스어 역본에서는 금주와 관련한 추가 표현이 전해지는 것으로 알려져 있으나, 이 원고는 그 역본의 특정 사본을 직접 대조한 판본비평 결과를 제시하지 않는다. 따라서 히브리어 본문이 말하는 범위와 역본 전승에 대한 추가 검증이 필요한 범위를 구별해야 한다."]},{"title":"성소의 기도와 엘리의 오해","paragraphs":["한나의 입술은 움직였으나 음성은 들리지 않았다(13절). 이 구체적인 묘사는 기도의 방식 자체에 대한 보편적 규정이라기보다, 엘리가 관찰할 수 있는 것과 한나가 실제로 하고 있는 일 사이의 차이를 드러낸다. 그의 판단은 정정되고 축복으로 바뀌지만, 이 사건 하나만으로 엘리의 모든 사역을 평가할 수는 없다. 2:12 이하의 엘리 아들들에 관한 서술과 함께 읽을 때 성소의 권위와 신실함의 관계가 더욱 복잡해진다."]},{"title":"‘벨리알의 딸’과 후속 장면의 대조","paragraphs":["16절의 בַּת־בְּלִיַּעַל은 ‘무가치함·불량함’과 관련된 관용 표현이다. 한나는 그런 사람으로 취급받지 않기를 구한다. 2:12에서는 엘리의 아들들이 유사한 표현으로 묘사된다. 독자는 오해받은 한나와 실제로 제사를 멸시하는 자들 사이의 대조를 읽을 수 있지만, 이것은 인접 본문을 함께 읽을 때 드러나는 문학적 관찰이지 1:16 한 절만의 명시적 설명은 아니다."]},{"title":"사무엘 이름의 해석과 정경적 위치","paragraphs":["20절의 설명은 ‘내가 여호와께 그를 구하였다’는 한나의 말에 초점이 있다. 히브리어 שְׁמוּאֵל의 어원에 관해서는 여러 설명이 논의되어 왔으므로, 이야기 속 말놀이를 확정된 역사언어학적 어원으로 바꾸지 않는다. 이후 사무엘은 이스라엘에서 말씀을 전하고 왕에게 기름을 붓는 인물이 된다(삼상 3장; 9–10장; 16장). 그러므로 그의 출생은 개인적 기도 응답이면서 왕정 전환의 서론이라는 정경적 의미를 갖는다. 다만 1:9–20 자체에는 아직 사울이나 다윗의 즉위 사건이 나오지 않는다."]}],"relatedResearch":[],"readerSources":[],"notes":["연구 참고자료","* 『성경전서 개역한글판』 · 대한성서공회 · 1961, 사무엘상 1:9–20 및 연결 본문 · 대한성서공회 저작권. 공개 재배포 허락은 별도 확인이 필요하다.\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · v2.2, 1Sam.1.9–20, 원문 및 형태 분석 · CC BY 4.0. 기반 히브리어 본문 Westminster Leningrad Codex(WLC)는 Public Domain이다.\n   * Original work of the Open Scriptures Hebrew Bible available at https://github.com/openscriptures/morphhb\n   * 사용 판본 원문: https://github.com/openscriptures/morphhb/blob/v.2.2/wlc/1Sam.xml\n* 『WORBS 본문연구 — 사무엘상 1장』 · Jude Lee / WORBS · 사무엘상 1:1–28, 2026년 7월 개정 연구 원고 v0.2 · 저작권 및 외부 이용 조건은 별도 확인 대상이다.","연구 및 재서술 안내","이 글은 사무엘상 1장 WORBS 기존 연구의 문학적 구조와 주해를 참조하고, 사무엘상 1:9–20의 히브리어 본문을 다시 살피며 독자용 한국어 문장으로 재구성하였다. 히브리어의 짧은 뜻풀이는 본문의 문맥을 설명하기 위해 한국어로 새로 서술하였다. 기존 연구와의 관계가 독립 저작물인지 파생 저작물인지는 별도의 권리 검토 없이 단정하지 않는다.","라이선스","원천별 조건은 서로 다르다. OSHB의 형태 분석 자료는 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)에 따르며, 기반 WLC 히브리어 본문은 Public Domain이다. 대한성서공회의 한국어 성경 본문과 기존 WORBS 연구의 권리는 각 권리자의 조건을 따른다. 이 원고 전체에 적용할 단일 라이선스와 외부 배포 권한은 아직 확정하지 않았다."],"sourceNotice":"연구 참고자료\n\n\n* 『성경전서 개역한글판』 · 대한성서공회 · 1961, 사무엘상 1:9–20 및 연결 본문 · 대한성서공회 저작권. 공개 재배포 허락은 별도 확인이 필요하다.\n* Open Scriptures Hebrew Bible (OSHB) · Open Scriptures Hebrew Bible Project · v2.2, 1Sam.1.9–20, 원문 및 형태 분석 · CC BY 4.0. 기반 히브리어 본문 Westminster Leningrad Codex(WLC)는 Public Domain이다.\n   * Original work of the Open Scriptures Hebrew Bible available at https://github.com/openscriptures/morphhb\n   * 사용 판본 원문: https://github.com/openscriptures/morphhb/blob/v.2.2/wlc/1Sam.xml\n* 『WORBS 본문연구 — 사무엘상 1장』 · Jude Lee / WORBS · 사무엘상 1:1–28, 2026년 7월 개정 연구 원고 v0.2 · 저작권 및 외부 이용 조건은 별도 확인 대상이다.\n\n\n연구 및 재서술 안내\n\n\n이 글은 사무엘상 1장 WORBS 기존 연구의 문학적 구조와 주해를 참조하고, 사무엘상 1:9–20의 히브리어 본문을 다시 살피며 독자용 한국어 문장으로 재구성하였다. 히브리어의 짧은 뜻풀이는 본문의 문맥을 설명하기 위해 한국어로 새로 서술하였다. 기존 연구와의 관계가 독립 저작물인지 파생 저작물인지는 별도의 권리 검토 없이 단정하지 않는다.\n\n\n라이선스\n\n\n원천별 조건은 서로 다르다. OSHB의 형태 분석 자료는 CC BY 4.0(https://creativecommons.org/licenses/by/4.0/)에 따르며, 기반 WLC 히브리어 본문은 Public Domain이다. 대한성서공회의 한국어 성경 본문과 기존 WORBS 연구의 권리는 각 권리자의 조건을 따른다. 이 원고 전체에 적용할 단일 라이선스와 외부 배포 권한은 아직 확정하지 않았다."}].forEach(function(r){a.push(r);});if(w.JBCResearch&&w.JBCResearch._done)w.JBCResearch._done("1sa");})(window);
